//! Contracts of the moving averages family, from `tests/fixtures/contract_moving_averages.txt`
//! (generated by `reference/kestrel_reference/fixtures/contract_moving_averages.py`).
//!
//! Every case runs through `build_checked`, so `values` covers the f64 registry surface; variants
//! only `build_typed` reaches are named per indicator below. The alert conventions of Donchian,
//! Keltner, Ichimoku, Supertrend, Parabolic SAR and MIDAS (and MIDAS `bars_since_extreme`) are
//! not described on their types; the generator states the reading the cases assume.

use super::Status::{Partial, Specified};
use super::{assert_holds, assert_rejected, Coverage};
use crate::common::contract::{load, ContractCase};
use kestrel_chartkit::IndicatorUnit;

const FIXTURE: &str = include_str!("../fixtures/contract_moving_averages.txt");

fn case(name: &str, indicator: &str, unit: IndicatorUnit) -> ContractCase {
    load(FIXTURE, name, indicator, unit)
}

/// Indicators of this family whose contract is not yet written. Moved into [`COVERAGE`] once
/// their cases exist; a name in neither list fails the matrix.
pub const PENDING: &[&str] = &[];

pub const COVERAGE: &[Coverage] = &[
    Coverage {
        indicator: "ema",
        values: Partial(
            "registry surface (first-sample seed); the build_typed init=sma seed is not in \
             the cases",
        ),
        alerts: Specified,
        configuration: Specified,
    },
    Coverage::full("wma"),
    Coverage::full("vwma"),
    Coverage::full("hma"),
    Coverage::full("dema"),
    Coverage::full("tema"),
    Coverage::full("kama"),
    Coverage::full("lsma"),
    Coverage::full("mcginley"),
    Coverage::full("t3"),
    Coverage::full("vidya"),
    Coverage::full("alligator"),
    Coverage::full("envelope"),
    Coverage {
        indicator: "twap",
        values: Partial(
            "registry surface (daily anchor, per-bar weighting, close); build_typed \
             weighting/anchor variants are not in the cases",
        ),
        alerts: Specified,
        configuration: Specified,
    },
    Coverage::full("vwap"),
    Coverage {
        indicator: "anchored_vwap",
        values: Partial(
            "registry surface (whole-day session, equal weight for zero volume); other \
             anchor kinds and the skip policy (build_typed) are not in the cases",
        ),
        alerts: Specified,
        configuration: Specified,
    },
    Coverage {
        indicator: "midas",
        values: Partial(
            "registry surface (Topfinder, hlc3); Bottomfinder, other sources and leading \
             zero-volume bars are not in the cases",
        ),
        alerts: Specified,
        configuration: Specified,
    },
    Coverage {
        indicator: "trend_relationship",
        values: Partial(
            "registry surface (EMA/EMA); the other smoother kinds of build_typed are not in \
             the cases",
        ),
        alerts: Specified,
        configuration: Specified,
    },
    Coverage::full("ichimoku"),
    Coverage::full("supertrend"),
    Coverage::full("parabolic_sar"),
    Coverage {
        indicator: "donchian",
        values: Specified,
        alerts: Partial(
            "new high / new low; a bar that is both the highest high and the lowest low \
             (precedence undocumented) is not in the cases",
        ),
        configuration: Specified,
    },
    Coverage::full("keltner"),
    Coverage {
        indicator: "bollinger",
        values: Partial(
            "registry surface (population divisor); the build_typed sample divisor is not \
             in the cases",
        ),
        alerts: Specified,
        configuration: Specified,
    },
];

